SELECT RATE_ID as rateId, CURRENCY_CODE as currencyCode, CURRENCY_NAME as currencyName, RATE_TYPE as rateType, EXCHANGE_RATE as exchangeRate, RATE_DATE as rateDate, IS_BASE_CURRENCY as isBaseCurrency, IS_ENABLED as isEnabled, BOOK_ID as bookId, TENANT_ID as tenantId, VERSION as version, CREATE_TIME as createTime, UPDATE_TIME as updateTime, CREATOR as creator, UPDATER as updater FROM T_CURRENCY_RATE WHERE IS_DELETED = 0
AND BOOK_ID = #{bookId,jdbcType=BIGINT}
AND TENANT_ID = #{tenantId,jdbcType=BIGINT}
AND CURRENCY_CODE LIKE '%' || #{currencyCode,jdbcType=VARCHAR} || '%'
AND CURRENCY_NAME LIKE '%' || #{currencyName,jdbcType=VARCHAR} || '%'
AND RATE_TYPE = #{rateType,jdbcType=INTEGER}
AND RATE_DATE >= #{rateDateStart,jdbcType=DATE}
AND RATE_DATE <= #{rateDateEnd,jdbcType=DATE}
AND IS_BASE_CURRENCY = #{isBaseCurrency,jdbcType=INTEGER}
AND IS_ENABLED = #{isEnabled,jdbcType=INTEGER}
ORDER BY RATE_DATE DESC, CURRENCY_CODE ASC

SELECT * FROM T_CURRENCY_RATE
WHERE IS_DELETED = 0
AND CURRENCY_CODE = #{currencyCode,jdbcType=VARCHAR}
AND RATE_DATE = #{rateDate,jdbcType=DATE}
AND BOOK_ID = #{bookId,jdbcType=BIGINT}
AND TENANT_ID = #{tenantId,jdbcType=BIGINT}

    AND RATE_ID != #{excludeId,jdbcType=BIGINT}

AND ROWNUM = 1

